/**
 * The provider marks this product is allowed to draw.
 *
 * A registry of path data rather than a dependency: six marks is a few
 * kilobytes of geometry with no package, no version and no supply chain, and
 * the alternative — an icon library — arrives with several thousand marks the
 * product will never draw and a maintainer nobody here has met.
 *
 * The geometry is each vendor's own published mark, taken as the vendor
 * publishes it and not redrawn. Every one of them is set in `currentColor`,
 * so a mark sits in the chrome it is placed in rather than importing a brand
 * palette into a design system whose whole rule is that colour belongs to the
 * data. That is a deliberate trade and it costs something: a mark that is only
 * identifiable by its hue is not identifiable here, which is why every mark
 * carries a name and why a call site that shows one alone owes the reader a
 * tooltip.
 *
 * **What is not here is the more important half.**
 *
 * - **Yandex Tracker.** No mark drawn. Yandex does not publish a monochrome
 *   mark for Tracker, and the product glyph is defined by its colour — drained
 *   to `currentColor` it is an unidentifiable shape rather than a quieter
 *   version of itself. Redrawing a trademark from memory is worse than
 *   spelling the provider's name, so `sources` spells it. See
 *   `SOURCE_KIND_BRAND` in `domains/sources/model/providers.ts`.
 * - **OpenAI and Anthropic.** No marks drawn, and not because of the artwork.
 *   The models registry stores a *wire*, not a vendor: `ModelWire` is
 *   `"openai" | "anthropic"` and it names the protocol an upstream speaks.
 *   The seed makes the gap plain — `ep_self_host` is a vLLM url on the
 *   cluster's own network sitting on the `openai` wire, and the vendors in
 *   that seed are `provider-A`/`provider-B`/`provider-C` precisely so that
 *   nobody reads a real account into a fictional one. A vendor mark beside a
 *   protocol column would assert a commercial relationship the row does not
 *   carry. The wire stays a word.
 */

/**
 * Every mark the kit can draw, in the order the product meets them: the three
 * ticket sources, the two compute backends, then the product's own.
 */
export const BRAND_IDS = [
  "github",
  "gitlab",
  "jira",
  "docker",
  "kubernetes",
  "comuki",
] as const

export type BrandId = (typeof BRAND_IDS)[number]

export interface BrandMark {
  /**
   * The vendor's own spelling of its name, and the mark's default accessible
   * name. A call site whose surface speaks in the product's lower-case voice
   * passes its own label instead; the mark's identity and the screen's copy are
   * two different things and neither should quietly become the other.
   */
  title: string
  /**
   * The artwork is wider than it is tall, so a square box would squash it. The
   * size step then sets the height and the width follows.
   */
  wide?: boolean
  /**
   * The published geometry, or `null` for the one mark the kit already ships
   * as a component of its own. Duplicating that path here would be two copies
   * of the same artwork drifting apart on the next revision.
   */
  art: { viewBox: string; path: string } | null
}

