/** Whether this kit has a mark for the given id. Narrows for a call site that
 *  holds a string — a provider kind read off a row, say — rather than a union. */
export function isBrandId(value: string): value is BrandId {
  return (BRAND_IDS as readonly string[]).includes(value)
}
